const lowStock=()=>products.filter(p=>p.active&&p.stock>0&&p.stock<=p.minimumStock),outStock=()=>products.filter(p=>p.active&&p.stock===0),byId=id=>products.find(p=>p.id===id),qty=n=>Number(n).toLocaleString('id-ID',{maximumFractionDigits:3}),dateText='25 September 2026';
