const matchProducts=(q,list=products)=>{q=q.trim().toLowerCase();const exact=list.filter(p=>p.aliases.some(a=>a.toLowerCase()===q)||p.internal.toLowerCase()===q);return (exact.length?exact:list.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(q))).sort((a,b)=>a.name.localeCompare(b.name,'id')||a.id.localeCompare(b.id));};
const button=(text,action,primary=false)=>'<button type="button" class="btn '+(primary?'primary':'')+'" data-action="'+action+'">'+text+'</button>';
function field(id,label,value='',attrs='',hint=''){return '<div class="field"><label for="'+id+'">'+label+'</label><input id="'+id+'" name="'+id+'" value="'+esc(value)+'" '+attrs+' aria-describedby="'+id+'-hint"><small id="'+id+'-hint">'+hint+'</small></div>';}
function select(id,label,values,value='',attrs=''){return '<div class="field"><label for="'+id+'">'+label+'</label><select id="'+id+'" name="'+id+'" '+attrs+'>'+values.map(v=>{const [key,text]=Array.isArray(v)?v:[v,v];return '<option value="'+esc(key)+'" '+(key===value?'selected':'')+'>'+esc(text)+'</option>';}).join('')+'</select></div>';}
function footer(){return '<footer class="footnote"><span>UI02 · Data contoh lokal · Tidak mengubah stok nyata</span><label class="review-switch">Peran review <select id="review-role" aria-label="Peran review">'+Object.entries(roles).map(([k,v])=>'<option value="'+k+'" '+(role===k?'selected':'')+'>'+v.label+'</option>').join('')+'</select></label></footer>';}
function bottomNavigation(){const items=role==='cashier'?[['Kasir','cash','pos'],['Sesi saya','history','session']]:role==='owner'?[['Dashboard','home','dashboard'],['Laporan','report','laporan']]:[['Dashboard','home','dashboard'],['Stok','box','stok']];return '<nav class="bottom-nav" aria-label="Navigasi bawah">'+items.map(([label,i,target])=>'<a href="'+routeURL(target)+'" '+(page===target?'aria-current="page"':'')+'>'+icon(i)+'<span>'+label+'</span></a>').join('')+'<button data-action="sidebar">'+icon('menu')+'<span>Menu</span></button><button data-action="account" aria-haspopup="dialog" aria-expanded="false">'+icon('user')+'<span>Akun</span></button></nav>';}
function catalog(){const stock=page==='stok'||page==='restock';return heading(page==='restock'?'Restock':stock?'Stok':'Produk',stock?'Satu stok usaha. Pantau jumlah tersedia dan prioritas pengisian.':'Cari produk lebih dahulu, lalu kelola identitas dan harga jual.',stock?'<a class="btn primary" href="'+routeURL('masuk')+'">'+icon('down')+'Barang Masuk</a>':'<a class="btn primary" href="'+routeURL('baru')+'">'+icon('plus')+'Tambah produk</a>')+'<div class="operation-context"><span>'+lowStock().length+' produk menipis · '+outStock().length+' habis</span><span>'+dateText+'</span></div><section class="panel"><div class="catalog-toolbar"><label class="search">'+icon('search')+'<input id="catalog-query" aria-label="Cari nama, SKU, atau barcode" placeholder="Cari nama, SKU, atau barcode" value="'+esc(filters.q)+'"></label><button class="btn filter-toggle" data-action="toggle-filters" aria-expanded="false" aria-controls="catalog-filters">Filter · '+[filters.category,filters.brand,filters.status].filter(Boolean).length+' aktif</button><div id="catalog-filters" class="filter-fields">'+select('category-filter','Kategori',[['','Semua kategori'],...categories],filters.category)+select('brand-filter','Merek',[['','Semua merek'],'Sinar','Tulis',['none','Tanpa merek']],filters.brand)+select('status-filter','Status',[['','Semua status'],'Normal','Menipis','Habis',['inactive','Nonaktif']],filters.status)+'</div></div><div id="catalog-results"></div></section><div class="support-actions">'+(role==='owner'?'<a class="btn quiet" href="'+routeURL('awal')+'">Stok awal '+icon('arrow')+'</a>':'')+'<a class="btn quiet" href="'+routeURL('kategori')+'">Kelola kategori</a><details class="demo-states"><summary>State review</summary>'+button('Contoh loading','loading')+button('Contoh gagal','error')+button('Pulihkan','recover')+'</details></div>';}
function catalogResults(){const host=$('#catalog-results');if(!host)return;if(queryState!=='ready'){host.innerHTML='<div class="empty-result" role="status">'+(queryState==='loading'?'Memuat halaman produk…':'Produk belum dapat dimuat. Jumlah stok tidak dinyatakan nol.')+button(queryState==='error'?'Coba lagi':'Selesaikan contoh','recover')+'</div>';host.setAttribute('aria-busy',queryState==='loading');return;}host.removeAttribute('aria-busy');const found=matchProducts(filters.q).filter(p=>(!filters.category||p.category===filters.category)&&(!filters.brand||(filters.brand==='none'?!p.brand:p.brand===filters.brand))&&(!filters.status||(filters.status==='inactive'?!p.active:stateOf(p)===filters.status))&&(page!=='restock'||p.active&&p.stock<=p.minimumStock));const pages=Math.max(1,Math.ceil(found.length/25));filters.index=Math.min(filters.index,pages-1);const shown=found.slice(filters.index*25,filters.index*25+25);host.innerHTML=shown.length?'<table class="product-table"><thead><tr><th>Produk / SKU</th><th>Kategori / satuan</th><th>Harga jual</th><th>Stok</th><th>Minimum</th><th>Status</th><th><span class="sr-only">Tindakan</span></th></tr></thead><tbody>'+shown.map(p=>'<tr><td data-label="Produk"><a class="product-title" href="'+routeURL('detail',p.id)+'">'+esc(p.name)+'</a><small>'+p.sku+(p.brand?' · '+esc(p.brand):'')+'</small></td><td data-label="Kategori">'+esc(p.category)+'<small>'+p.unit+'</small></td><td data-label="Harga jual">'+money(p.price)+'</td><td data-label="Stok">'+qty(p.stock)+' '+p.unit+'</td><td data-label="Minimum">'+qty(p.minimumStock)+'</td><td data-label="Status">'+(p.active?badge(p):'<span class="badge">Nonaktif</span>')+'</td><td data-label="Tindakan"><a class="btn quiet" href="'+routeURL('detail',p.id)+'">Detail '+icon('arrow')+'</a></td></tr>').join('')+'</tbody></table><div class="table-footer"><span>'+(filters.index*25+1)+'–'+(filters.index*25+shown.length)+' dari '+found.length+' hasil contoh · 25 per halaman</span><div class="pagination"><button class="icon-button" data-page="-1" aria-label="Halaman sebelumnya" '+(!filters.index?'disabled':'')+'>'+icon('arrow')+'</button><span>Halaman '+(filters.index+1)+' / '+pages+'</span><button class="icon-button" data-page="1" aria-label="Halaman berikutnya" '+(filters.index===pages-1?'disabled':'')+'>'+icon('arrow')+'</button></div></div>':'<div class="empty-result"><h2>Produk tidak ditemukan</h2><p>Coba nama, SKU, barcode, atau hapus filter.</p>'+button('Hapus filter','clear-filters')+'</div>';}
function productDetail(){const p=byId(selectedId);if(!p)return missing();return heading(esc(p.name),p.sku+' · '+(p.active?'Produk aktif':'Nonaktif, tidak dapat dipilih untuk posting'),'<a class="btn primary" href="'+routeURL('edit',p.id)+'">Edit produk</a>')+'<section class="panel"><div class="panel-head"><h2>Identitas produk</h2>'+badge(p)+'</div><dl class="profile-fields">'+[['Kategori',p.category],['Merek',p.brand||'Tanpa merek'],['Satuan / presisi',p.unit+' / '+p.precision+' desimal'],['Harga jual',money(p.price)],['Stok saat ini',qty(p.stock)+' '+p.unit],['Stok minimum',qty(p.minimumStock)],['Barcode internal',p.internal],['Alias produsen',p.aliases.join(', ')||'Belum ada']].map(([k,v])=>'<div class="profile-line"><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div class="profile-actions"><a class="btn" href="'+routeURL('label',p.id)+'">'+icon('barcode')+'Barcode & label</a><a class="btn quiet" href="'+routeURL('produk')+'">Kembali ke produk</a></div></section>'+(role==='owner'?'<p class="note">Bukti biaya tersedia pada rincian pergerakan terkait. Harga jual bukan biaya perolehan.</p>':'');}
