document.addEventListener('submit',e=>{e.preventDefault();if(role==='cashier')return;
 if(e.target.id==='header-search-form'){filters.q=$('#header-search').value;filters.index=0;location.hash=role+'/produk';render();return;}
 if(e.target.id==='product-form'){const data=Object.fromEntries(new FormData(e.target)),old=page==='edit'?byId(selectedId):null;const p={sku:data.sku.trim().toUpperCase(),name:data.name.trim(),category:data.category,brand:data.brand.trim(),unit:old?.ledger?old.unit:data.unit.trim(),precision:old?.ledger?old.precision:Number(data.precision),active:data.active==='true',price:Number(data.price),minimumStock:Number(data.minimumStock),barcode:(data.barcode||'').replace(/^ +| +$/g,'')};const error=!p.name||!p.sku||!p.unit?'Isi nama, SKU dan satuan.':tokenError(p.barcode)||(!amountValid(p.minimumStock,p,true)?'Minimum stok harus mengikuti presisi satuan.':'');if(error){$('#form-error').textContent=error;return;}if(old){if(exactCollision(p,old.id).length){$('#form-error').textContent='SKU sudah digunakan produk lain.';return;}Object.assign(old,p,{active:data.active==='true',version:old.version+1});delete old.barcode;notice='Master produk contoh diperbarui. Stok dan fakta pergerakan tidak diubah.';location.hash=role+'/detail/'+old.id;}else{createDraft=p;duplicateReview();}return;}
 if(e.target.id==='alias-form'){const value=$('#alias').value.replace(/^ +| +$/g,'');const error=tokenError(value)||(products.some(p=>p.internal===value||p.aliases.includes(value))?'Barcode sudah terdaftar. Alias tidak boleh dipakai ulang.':'');if(error){$('#alias-error').textContent=error;return;}byId(selectedId).aliases.push(value);render();return;}
 if(e.target.id==='category-form'){const name=$('#category-name').value.trim();if(!name||categories.some(c=>c.toLowerCase()===name.toLowerCase())){$('#category-error').textContent='Isi nama kategori baru yang belum digunakan.';return;}categories.push(name);render();return;}
 if(e.target.id==='lookup-form'){const token=$('#lookup-query').value.replace(/^ +| +$/g,'');if(!token)return;const p=products.find(p=>p.sku.toLowerCase()===token.toLowerCase()||p.internal===token||p.aliases.includes(token));if(p?.active&&(page!=='awal'||!p.ledger&&!p.opened)){addDraft(p.id);$('#lookup-query').value='';lookup();}else{$('#announcement').textContent='Kode belum dapat dipilih. Token dipertahankan; cari produk atau periksa identitas.';lookup();}return;}
 if(e.target.id==='movement-form'){reviewMovement();return;}
 if(e.target.id==='correction-form'){if(role!=='owner')return;const m=history.find(m=>m.id===$('#original').value),p=byId(m.product),kind=$('#correction-kind').value,delta=kind==='REVERSAL'?-m.delta:Number($('#verified-count').value)-p.stock;let error='';if(kind==='REVERSAL'&&!['OPENING','RECEIPT','MANUAL_ISSUE'].includes(m.type))error='Pergerakan penjualan/retur tidak dapat dibalik mandiri. Gunakan koreksi komersial terkait.';else if(kind==='REVERSAL'&&history.some(h=>h.type==='REVERSAL'&&h.original===m.id))error='Fakta ini sudah memiliki pembalikan penuh.';else if(!delta)error='Hitungan sama dengan stok. Tidak perlu membuat pergerakan.';else if(p.stock+delta<0)error='Pembalikan membuat stok negatif. Tinjau fakta dan stok tersedia.';else if(!amountValid(Math.abs(delta),p))error='Jumlah harus mengikuti presisi satuan.';if(error){$('#correction-error').textContent=error;return;}review={correction:true,original:m.id,kind,delta,version:p.version,reason:$('#correction-reason').value.trim(),ref:$('#correction-ref').value.trim(),unknown:kind==='REVERSAL'?m.costState!=='KNOWN':$('#adjust-unknown').checked,cost:kind==='REVERSAL'?privateEvidence.get(m.id)?.unitCost:$('#adjust-unit-cost').value};dialog('Tinjau koreksi','<p><strong>'+m.id+'</strong> tetap tersimpan.</p><p>'+esc(p.name)+'</p><dl class="correction-impact"><div><dt>Stok sekarang</dt><dd>'+qty(p.stock)+' '+p.unit+'</dd></div><div><dt>Perubahan</dt><dd>'+(delta>0?'+':'')+qty(delta)+' '+p.unit+'</dd></div><div><dt>Setelah konfirmasi</dt><dd>'+qty(p.stock+delta)+' '+p.unit+'</dd></div></dl><p>Alasan: '+esc(review.reason)+'</p><p>Referensi: '+esc(review.ref)+'</p><p class="note">Produksi wajib memeriksa ketergantungan valuasi dan otorisasi ulang sebelum mencatat koreksi.</p><p id="commit-error" class="inline-error" role="alert"></p><div class="form-actions">'+button('Batal','close-detail')+button('Tambahkan fakta koreksi contoh','confirm-correction',true)+'</div>');}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&($('#account').matches(':popover-open')||$('#utility').matches(':popover-open'))){e.preventDefault();e.stopPropagation();const trigger=$('#account').matches(':popover-open')?accountTrigger:utilityTrigger;closePopovers();trigger?.focus();}},true);
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')){const r=e.target.getBoundingClientRect();if(e.clientX>r.right||e.clientX<r.left){navScroll[role]=$('#drawer .navigation').scrollTop;closePopovers();$('#drawer').close();}}});
$('#drawer').addEventListener('close',()=>{closePopovers();document.body.append($('#account'));});
for(const id of ['account','utility'])$('#'+id).addEventListener('toggle',e=>{if(e.newState==='closed')(id==='account'?accountTrigger:utilityTrigger)?.setAttribute('aria-expanded','false');});
document.addEventListener('scroll',e=>{if(e.target.matches?.('.navigation')&&e.target.clientHeight)navScroll[role]=e.target.scrollTop;},true);
window.addEventListener('resize',()=>{closePopovers();if(innerWidth>=1024&&$('#drawer').open)$('#drawer').close();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);const h=$('h1');h.tabIndex=-1;h.focus({preventScroll:true});});
render();
